    const buffer = fs.readFileSync(filePath);
    const workbook = XLSX.read(buffer, { type: 'buffer' });
    const sheetName = workbook.SheetNames[0]; // Assume we are comparing the first sheet
    const worksheet = workbook.Sheets[sheetName];
